import subprocess
# Check pages 6-8 for section headers
for pg in range(5, 9):
    r = subprocess.run(['pdftotext', '-f', str(pg), '-l', str(pg), '-layout', 'main.pdf', '-'], capture_output=True, text=True)
    lines = r.stdout.strip().split('\n')
    print(f'--- Page {pg} ---')
    for l in lines:
        stripped = l.strip()
        # Look for numbered section headers
        if any(stripped.startswith(f'{n} ') for n in ['2','3','4','5','6']):
            if len(stripped) < 60:
                print(f'  Section: {stripped}')
        if 'Limitation' in l or 'Reference' in l:
            if len(l.strip()) < 40:
                print(f'  {l.strip()}')
    # Also print last line to see density
    print(f'  (last content: {lines[-2].strip()[:60] if len(lines) > 1 else \"\"})') 
" 2>&1

